const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const contents={bio:`<p class="eyebrow">Trayectoria</p><h2>Una vida dedicada a la historia</h2><p>Germán Rodrigo Mejía Pavony nació en Pereira en 1954. Es licenciado en Filosofía y Letras con especialización en Historia de la Pontificia Universidad Javeriana y doctor en Historia de América Latina de la Universidad de Miami.</p><p>Fue decano de la Facultad de Ciencias Sociales de la Universidad Javeriana y director del Archivo de Bogotá. Su trabajo vincula la historia urbana, la investigación, la docencia y la divulgación.</p><p>Continúa compartiendo su conocimiento en conferencias, encuentros académicos y conversaciones de radio.</p><a href="https://javeriana.academia.edu/Germ%C3%A1nMej%C3%ADa/CurriculumVitae" target="_blank" rel="noopener">Consultar hoja de vida en Academia.edu ↗</a><p class="notice">La hoja de vida enlazada es una versión histórica y no recoge toda su actividad reciente.</p>`,talks:`<p class="eyebrow">Conferencias y encuentros</p><h2>Diálogos para comprender nuestro tiempo</h2><h3>Bogotá: ciudad y memoria</h3><p>La ciudad colonial, sus transformaciones urbanas y las historias de sus habitantes.</p><h3>Colombia: historia y sociedad</h3><p>La construcción del país, sus procesos históricos y las preguntas sobre nuestro pasado.</p><h3>América Latina: una historia urbana</h3><p>Las ciudades latinoamericanas y las relaciones entre territorio, sociedad e historia.</p><p>El tema y el formato de cada conferencia, taller o clase se acuerdan con la institución.</p><button class="button" data-open="invite">Preparar una invitación</button>`,book1:`<h2>Los años del cambio</h2><img class="detail-cover" src="assets/los-anos-del-cambio-fast.webp" alt="Los años del cambio"><p>Historia urbana de Bogotá, 1820–1910.</p><p>Germán Rodrigo Mejía Pavony. Primera edición de 1999; segunda edición de 2000.</p><a href="https://www.tornamesa.co/autor/german-rodrigo-mejia-pavony/" target="_blank" rel="noopener">Consultar catálogo del autor ↗</a>`,book2:`<h2>La ciudad de los conquistadores</h2><img class="detail-cover" src="assets/la-ciudad-de-los-conquistadores-original.webp" alt="La ciudad de los conquistadores"><p>Historia de Bogotá, 1536–1604.</p><p>Germán Rodrigo Mejía Pavony. Editorial Pontificia Universidad Javeriana, 2012.</p><a href="https://javeriana.academia.edu/GermanMejiaPavony" target="_blank" rel="noopener">Consultar publicaciones del autor ↗</a>`,book3:`<h2>La aventura urbana de América Latina</h2><img class="detail-cover" src="assets/la-aventura-urbana-original.webp" alt="La aventura urbana de América Latina"><p>Germán Rodrigo Mejía Pavony. Fundación Mapfre / Taurus, 2013.</p><a href="https://www.penguinlibros.com/es/994620-german-r-mejia-pavony" target="_blank" rel="noopener">Consultar en Penguin Libros ↗</a>`,invite:`<p class="eyebrow">Conferencias · Talleres · Clases</p><h2>Preparemos una conversación</h2><p class="notice">El canal de contacto directo está pendiente de confirmación. Puede preparar y descargar su invitación; este formulario todavía no envía mensajes.</p><form id="invite-form"><label>Nombre<input name="nombre" required autocomplete="name"></label><label>Institución<input name="institucion" required autocomplete="organization"></label><label>Correo electrónico<input name="correo" type="email" required autocomplete="email"></label><label>Formato<select name="formato"><option>Conferencia</option><option>Taller</option><option>Clase o seminario</option><option>Entrevista</option></select></label><label>Fecha y lugar previstos<input name="lugar" placeholder="Ciudad, modalidad y fecha aproximada"></label><label>Cuéntenos sobre el encuentro<textarea name="mensaje" required></textarea></label><button class="button" type="submit">Descargar borrador de invitación</button><p class="status" aria-live="polite"></p></form>`,credits:`<h2>Créditos y fuentes</h2><p>Hero: montaje de doce segundos en 768p a partir de la imagen aprobada y tres fotografías históricas suministradas. Fotografías históricas con ajuste conservador de contraste y nitidez. Movimiento recreado con MiniMax Hailuo 2.3 a 768p y acelerado para un efecto timelapse; no es una filmación histórica. Apertura a color animada con movimiento del cielo y la plaza. Carátulas originales con un ajuste conservador de nitidez, sin rediseño.</p><p>Fotografías de Germán y del estudio de radio: materiales suministrados para este proyecto.</p><p>Plaza de Bolívar: Gabriel Leonardo Guerrero / DeMentePhoto, Wikimedia Commons, CC BY-SA 4.0. <a href="https://commons.wikimedia.org/wiki/File:Panor%C3%A1mica_Plaza_de_Bol%C3%ADvar_Bogot%C3%A1.jpg" target="_blank" rel="noopener">Wikimedia Commons</a>.</p><p>Portadas editoriales: fuentes bibliográficas enlazadas. Ilustraciones temáticas generadas para esta propuesta.</p><p>Fuentes de trayectoria: hoja de vida en Academia.edu y perfiles institucionales de la Universidad Javeriana.</p><p>Versión de desarrollo: los homenajes y el canal de contacto definitivo están pendientes de incorporación.</p>`};
const dialog=document.querySelector('dialog'),body=document.querySelector('#dialog-content');let lastFocus;function openDetail(key){if(!contents[key])return;lastFocus=document.activeElement;body.innerHTML=contents[key];if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.scrollTop=0}document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openDetail(b.dataset.open)});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});document.addEventListener('submit',e=>{if(e.target.id!=='invite-form')return;e.preventDefault();const data=new FormData(e.target);const text=Array.from(data,([k,v])=>`${k.toUpperCase()}: ${v}`).join('\n\n');const url=URL.createObjectURL(new Blob(['INVITACIÓN A GERMÁN RODRIGO MEJÍA PAVONY\n\n'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='invitacion-german-mejia.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);e.target.querySelector('.status').textContent='Borrador descargado. No se ha enviado ningún mensaje.'});



const heroVideo=document.querySelector('.hero-video');if(heroVideo){const startVideo=()=>{heroVideo.muted=true;if(!heroVideo.src)heroVideo.src=heroVideo.dataset.src;heroVideo.play().catch(()=>{});};const cover=document.querySelector('.hero>img');heroVideo.addEventListener('playing',()=>heroVideo.closest('.hero').classList.add('video-ready'));heroVideo.addEventListener('error',()=>heroVideo.closest('.hero').classList.remove('video-ready'));if(cover&&!cover.complete)cover.addEventListener('load',startVideo,{once:true});else startVideo();document.addEventListener('visibilitychange',()=>{if(document.hidden)heroVideo.pause();else startVideo();});}

